// Récupère le mapping JSON produit par le LLM + prépare la ligne de staging.
const out = [];
const batchId = 'ING-' + $now.toFormat('yyyyLLdd-HHmmss');
const cible = $('Formulaire').first().json['Table cible'];
const fichier = ($('Formulaire').first().json['Fichier'] && $('Formulaire').first().json['Fichier'].filename) || 'upload';
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json.response ?? items[i].json.message?.content ?? '';
  let mapped = {};
  try {
    const cleaned = String(resp).replace(/^```(json)?/i, '').replace(/```$/,'').trim();
    mapped = JSON.parse(cleaned);
  } catch (e) {
    mapped = { _erreur_parse: String(resp).slice(0, 500) };
  }
  // La ligne source d'origine = l'entrée du Merge (sans le champ 'cols' du schéma).
  const src = { ...items[i].json };
  delete src.cols; delete src.response; delete src.message; delete src.model; delete src.created_at; delete src.done;
  out.push({ json: {
    batch_id: batchId,
    source_file: fichier,
    target_table: cible,
    row_index: i + 1,
    source_row: JSON.stringify(src),
    mapped: JSON.stringify(mapped)
  }});
}
return out;
